import { BALANCE } from '../config/balance.js';

export const WORDS_PER_UNIT = BALANCE.VOCA?.WORDS_PER_UNIT || 7;
export const ESTIMATED_TOTAL_WORDS = 4819;
export const DEFAULT_TOTAL_UNITS = 689;

/**
 * 비석 표시용 뜻 8글자 이내 정제
 * @param {string} rawMeaning
 * @param {number} [maxChars=BALANCE.VOCA?.MEANING_MAX_CHARS || 8]
 * @returns {string}
 */
export function sanitizeMeaning(rawMeaning, maxChars = BALANCE.VOCA?.MEANING_MAX_CHARS || 8) {
  if (!rawMeaning) return '';
  const parts = String(rawMeaning).split('/');
  let candidate = parts[0];
  if (parts.length > 1 && /(?:인명|지명|성씨)/.test(candidate)) {
    candidate = parts.find((p) => !/(?:인명|지명|성씨)/.test(p)) || parts[0];
  }
  let text = String(candidate)
    .replace(/\([^)]*\)/g, '')
    .replace(/[a-zA-Z]/g, '')
    .split(/[,;·]/)[0]
    .trim();
  if (!text) {
    text = String(rawMeaning)
      .replace(/\([^)]*\)/g, '')
      .replace(/[a-zA-Z]/g, '')
      .trim();
  }
  if (!text) {
    const match = String(rawMeaning).match(/[가-힣]+/);
    if (match) text = match[0];
  }
  if (text.length > maxChars) {
    text = text.slice(0, maxChars).trim();
  }
  return text;
}

